@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum ApproveAndSwap {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""


    public enum RevertReason : Equatable, Error {
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = []
    public static let functions: [ABI.Function] = [swapExactInFn]
    public static let swapExactInFn = ABI.Function(
            name: "swapExactIn",
            inputs: [.address, .address, .uint256, .address, .uint256, .address, .uint256, .address, .bool],
            outputs: []
    )

    public static func swapExactIn(filler: EthAddress, sellToken: EthAddress, sellAmount: Number, buyToken: EthAddress, minBuyAmount: Number, feeToken: EthAddress, feeAmount: Number, feeRecipient: EthAddress, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try swapExactInFn.encoded(with: [.address(filler), .address(sellToken), .uint256(sellAmount), .address(buyToken), .uint256(minBuyAmount), .address(feeToken), .uint256(feeAmount), .address(feeRecipient), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try swapExactInFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, swapExactInFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func swapExactInDecode(input: Hex) throws -> (EthAddress, EthAddress, Number, EthAddress, Number, EthAddress, Number, EthAddress, Bool) {
        let decodedInput = try swapExactInFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple9(.address(filler), .address(sellToken), .uint256(sellAmount), .address(buyToken), .uint256(minBuyAmount), .address(feeToken), .uint256(feeAmount), .address(feeRecipient), .bool(cappedMax)):
            return  (filler, sellToken, sellAmount, buyToken, minBuyAmount, feeToken, feeAmount, feeRecipient, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, swapExactInFn.inputTuple)
        }
    }

}